&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet p-rich_text_list--nested&quot; data-stringify-type=&quot;unordered-list&quot; data-list-tree=&quot;true&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;5+ years of consultative sales experience, ideally in automotive.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Motivated self-starters who thrive in a fast-paced environment.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Willingness to travel frequently within the region.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Apply Now:&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
